import { describe, expect, test } from "bun:test";
import { fetch } from "./index";

describe("GET /", () => {
  test("returns success message as JSON", async () => {
    const response = fetch(new Request("http://localhost/"));

    expect(response.status).toBe(200);
    expect(response.headers.get("content-type")).toContain("application/json");
    expect(await response.json()).toEqual({ success: true, message: "Hello world" });
  });
});

describe("GET /about-us", () => {
  test("returns the about-us HTML page", async () => {
    const response = fetch(new Request("http://localhost/about-us"));

    expect(response.status).toBe(200);
    expect(response.headers.get("content-type")).toContain("text/html");

    const body = await response.text();
    expect(body).toContain("ABOUT US");
  });
});

describe("unknown routes", () => {
  test("returns 404", () => {
    const response = fetch(new Request("http://localhost/unknown"));

    expect(response.status).toBe(404);
  });
});

describe("integration", () => {
  test("server responds over HTTP", async () => {
    const server = Bun.serve({ port: 0, fetch });

    try {
      const response = await globalThis.fetch(`http://localhost:${server.port}/`);

      expect(response.status).toBe(200);
      expect(await response.json()).toEqual({ success: true, message: "Hello world" });
    } finally {
      server.stop(true);
    }
  });
});

